"""Module 5 -- free hypothesis search (TZ 9.5), logical-analysis approach.

TZ 9.5 ("Модуль свободного поиска нарушений") asks for findings that fall
*outside* the 132-parameter matrix, generated by up to four independent
discovery methods (logical analysis / semantic dissonance / normative
analysis / ML pattern analysis). Before this module, the only code that
produced a `SUSPICION` finding was `_create_gold_fixture_groups` in
`v3_pipeline.py`, which has no caller anywhere in `app` and, even if wired
in, only replays organizer-provided fixtures rather than computing a
hypothesis -- i.e. the module was entirely dead.

This file implements exactly one of the four approaches -- LOGICAL_ANALYSIS
("if A then B") -- for real, against actually extracted data, and is honest
about the other three still being unimplemented:

- SEMANTIC_DISSONANCE: not implemented here (see `semantic_dissonance.py`
  for a second, independent approach, wired in separately).
- NORMATIVE_ANALYSIS (a general SP/GOST/SanPiN checker outside the matrix):
  not implemented. The `LogicalRule` table below cites real normative
  paragraphs, but there is no general-purpose normative-document engine --
  every rule is hand-authored, not derived from a machine-readable norms
  base.
- ML_PATTERN_ANALYSIS: not implemented (no historical-anomaly model
  exists in this codebase yet).

A rule fires only when a real numeric value was actually extracted for its
condition parameter this run (an unparseable/missing condition is an honest
abstention, not a suspicion) *and* the implied check comes back negative.
"Negative" here means "no corroborating evidence was found", which is a
signal for the inspector to look, not proof that the implied fact is false
-- consistent with TZ 9.5's own framing of a Suspicion as a hypothesis, not
a violation (see `finding_status = SUSPICION`, excluded from
`training_release.FORBIDDEN_TRAINING_LABELS` and from every violation count
in `protocol_annex2.py`).
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any

from sqlalchemy.orm import Session

from ..db.models import DocumentVersion, EvidenceFragment, EvidenceGroup, InspectionProcess, LogicalRuleRecord, Param, SourceFragment, Suspicion
from .evidence_groups import upsert_evidence_group
from .normalization import normalize_text


DISCOVERY_METHOD_LOGICAL_ANALYSIS = "LOGICAL_ANALYSIS"
MODEL_VERSION_LOGICAL_ANALYSIS = "logical-analysis-v1"

_NUMBER_RE = re.compile(r"-?\d+(?:[.,]\d+)?")


@dataclass(frozen=True)
class LogicalRule:
    """One row of the TZ-10 `Logical_Rules` table (`id, rule_name, condition,
    expected, normative_base, is_active`), expanded into the fields this
    engine needs to evaluate it. `condition` = (condition_param_code,
    condition_op, condition_value); `expected` = the implied check."""

    rule_id: str
    rule_name: str
    is_active: bool
    condition_param_code: str
    condition_op: str  # ">" | ">=" | "<" | "<=" | "=="
    condition_value: float
    condition_description: str
    implied_check: str  # "PARAM_EVIDENCE_PRESENT" | "TEXT_KEYWORD_PRESENT"
    implied_description: str
    normative_base: str
    criticality: str  # "КРИТИЧЕСКОЕ" | "СУЩЕСТВЕННОЕ"
    confidence: float
    implied_param_code: str | None = None
    implied_discipline: str | None = None
    implied_keywords: tuple[str, ...] = field(default_factory=tuple)


